@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --font-sans: var(--font-inter, Inter), ui-sans-serif, system-ui, sans-serif;
  --font-heading: var(--font-sans);
