// Series step down from the primary toward the background, so charts follow the theme.
export const chartTones = [
  "var(--primary)",
  "color-mix(in oklch, var(--primary) 62%, var(--background))",
  "color-mix(in oklch, var(--primary) 38%, var(--background))",
  "color-mix(in oklch, var(--primary) 22%, var(--background))",
  "color-mix(in oklch, var(--primary) 12%, var(--background))",
]

export type ChartConfig = Record<
  string,
  {
    label?: string
    color?: string
  }
>

export type ChartTooltipPayload = {
  dataKey?: string
  name?: string
  value?: unknown
  color?: string
}

export type ChartLegendPayload = {
  dataKey?: string
  value?: string
  color?: string
}

export function chartColor(key: string) {
  return `var(--color-${key})`
}

export function chartVars(config: ChartConfig): Record<string, string> {
  const style: Record<string, string> = {}
  Object.entries(config).forEach(([key, item], index) => {
    style[`--color-${key}`] = item.color ?? chartTones[index % chartTones.length]
  })
  return style
}

export function formatChartValue(value: unknown) {
  if (typeof value === "number") {
    return value.toLocaleString("en-US")
  }
  if (Array.isArray(value)) {
    return value.map((item) => String(item)).join(" – ")
  }
  return value == null ? "" : String(value)
}

export interface ChartContext {
  config: ComputedRef<ChartConfig>
  /** Set by ChartGrid, drawn by the axes: horizontal lines on the y axis, vertical on the x axis. */
  grid: { horizontal: boolean; vertical: boolean }
}

export const chartKey: InjectionKey<ChartContext> = Symbol("Chart")

export function useChart(): ChartContext {
  return inject(chartKey, {
    config: computed(() => ({})),
    grid: reactive({ horizontal: false, vertical: false }),
  })
}

import type { ComputedRef, InjectionKey, Ref } from "vue"

/** Scores an item against the search: 0 hides it, higher is a better match. */
export type CommandFilter = (value: string, search: string, keywords?: string[]) => number

export type CommandItemEntry = {
  value: string
  keywords: string[]
  groupId?: string
  forceMount: boolean
}

export type CommandContext = {
  search: Ref<string>
  shouldFilter: ComputedRef<boolean>
  register: (id: string, entry: CommandItemEntry) => void
  unregister: (id: string) => void
  isItemVisible: (id: string) => boolean
  isGroupVisible: (groupId: string) => boolean
  visibleCount: ComputedRef<number>
}

export const commandContextKey: InjectionKey<CommandContext> = Symbol("Command")
export const commandGroupKey: InjectionKey<string> = Symbol("CommandGroup")

/**
 * The default filter: a prefix or word start scores highest, then a substring,
 * then the search letters in order (fuzzy). Case and accents are ignored.
 */
export const defaultCommandFilter: CommandFilter = (value, search, keywords) => {
  const normalize = (text: string) =>
    text.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim()
  const query = normalize(search)
  if (!query) return 1
  const haystack = normalize([value, ...(keywords ?? [])].join(" "))
  if (haystack.startsWith(query)) return 1
  if (new RegExp(`(^|[\\s\\-_/])${query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`).test(haystack)) return 0.9
  if (haystack.includes(query)) return 0.8
  let index = 0
  let gaps = 0
  for (const char of query) {
    const found = haystack.indexOf(char, index)
    if (found === -1) return 0
    gaps += found - index
    index = found + 1
  }
  return Math.max(0.1, 0.6 - gaps * 0.02)
}

