  [data-slot="tabs-list"][data-variant="line"][data-high-contrast="true"][data-color="crimson"] {
    --tabs-line: var(--crimson-ink-strong);
    --tabs-active: var(--crimson-ink-strong);
  }
  [data-slot="tabs-list"][data-variant="line"][data-high-contrast="true"][data-color="jade"] {
    --tabs-line: var(--jade-ink-strong);
    --tabs-active: var(--jade-ink-strong);
  }

  [data-slot="tabs-panels"] {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
  }

  [data-slot="tabs-panel"] {
    grid-area: 1 / 1;
  }

  @media (prefers-reduced-motion: no-preference) {
    [data-slot="tabs-panel"][data-state="active"] {
      animation: lumen-tabs-panel-in 175ms ease;
    }
  }

  @keyframes lumen-tabs-panel-in {
    from {
      opacity: 0;
    }
  }
}

export type Time = { hours: number; minutes: number }

export type TimeOption = { value: number; label: string }

export function parseTime(value: string | undefined | null): Time | undefined {
  const match = value?.match(/^(\d{1,2}):(\d{2})$/)
  if (!match) return undefined
  const hours = Number(match[1])
  const minutes = Number(match[2])
  if (hours > 23 || minutes > 59) return undefined
  return { hours, minutes }
}

export const pad = (n: number) => String(n).padStart(2, "0")

export function toValue({ hours, minutes }: Time) {
  return `${pad(hours)}:${pad(minutes)}`
}

export function formatTime(time: Time, hourCycle: 12 | 24) {
  if (hourCycle === 24) return toValue(time)
  const period = time.hours < 12 ? "AM" : "PM"
  const hours = time.hours % 12 === 0 ? 12 : time.hours % 12
  return `${hours}:${pad(time.minutes)} ${period}`
}

/* Reka unmounts a toast when its animation ends, not its transition, so the
   enter and exit moves of Base UI's data-starting-style / data-ending-style are
   keyframes here. A one-sided keyframe animates from or to the stacked transform. */
@keyframes lumen-toast-enter {
  from {
    transform: translateY(150%);
  }
}

@keyframes lumen-toast-exit {
  to {
    transform: translateY(150%);
    opacity: 0;
  }
}

@keyframes lumen-toast-exit-right {
  from {
    transform: translateX(var(--reka-toast-swipe-end-x, 0px)) translateY(var(--offset-y));
  }
  to {
    transform: translateX(calc(var(--reka-toast-swipe-end-x, 0px) + 150%)) translateY(var(--offset-y));
    opacity: 0;
  }
}

@keyframes lumen-toast-exit-left {
  from {
    transform: translateX(var(--reka-toast-swipe-end-x, 0px)) translateY(var(--offset-y));
  }
  to {
    transform: translateX(calc(var(--reka-toast-swipe-end-x, 0px) - 150%)) translateY(var(--offset-y));
    opacity: 0;
  }
}

@keyframes lumen-toast-exit-down {
  from {
    transform: translateY(var(--reka-toast-swipe-end-y, 0px));
  }
  to {
    transform: translateY(calc(var(--reka-toast-swipe-end-y, 0px) + 150%));
    opacity: 0;
  }
}

@keyframes lumen-toast-exit-up {
  from {
    transform: translateY(var(--reka-toast-swipe-end-y, 0px));
  }
  to {
    transform: translateY(calc(var(--reka-toast-swipe-end-y, 0px) - 150%));
    opacity: 0;
  }
}

@layer components {
  [data-slot="toast"][data-state="open"] {
    animation: lumen-toast-enter 0.5s cubic-bezier(0.22, 1, 0.36, 1);
  }

  [data-slot="toast"][data-state="closed"]:not([data-limited]) {
    animation: lumen-toast-exit 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  }

  [data-slot="toast"][data-state="closed"][data-swipe="end"][data-swipe-direction="right"] {
    animation-name: lumen-toast-exit-right;
  }
  [data-slot="toast"][data-state="closed"][data-swipe="end"][data-swipe-direction="left"] {
    animation-name: lumen-toast-exit-left;
  }
  [data-slot="toast"][data-state="closed"][data-swipe="end"][data-swipe-direction="down"] {
    animation-name: lumen-toast-exit-down;
  }
  [data-slot="toast"][data-state="closed"][data-swipe="end"][data-swipe-direction="up"] {
    animation-name: lumen-toast-exit-up;
  }
}

